    'hero.button.join': 'Join Our Family',
    'hero.button.learn': 'Learn More',
    'about.title': 'The Blood Paladins Legacy',
    'about.legacy.p1': 'are not just leaders. They are visionaries who saw beyond the chaos of war and the pursuit of power. In a realm where alliances crumble and leaders fall to greed, they chose a different path one paved with honor, loyalty, and an unbreakable bond that runs deeper than blood.',
    'about.legacy.p2': 'Their dream was simple yet profound: to build a',
    'about.legacy.p2.family': 'family',
    'about.legacy.p2.rest': '. Not an organization. Not a hierarchy. A true family where every member stands shoulder to shoulder, where honor is not just a word but a way of life, and where loyalty means you would lay down your life for your brother or sister without hesitation.',
    'about.legacy.quote': 'In Blood Paladins, we don\'t just fight together. We die for each other.',
    'about.legacy.quote.by': '— Pryda & LundiX',
    'about.legacy.p3': 'This is not empty rhetoric. This is the foundation upon which Blood Paladins stands.',
    'about.legacy.p3.lead': 'lead by example, showing that true strength comes not from commanding others, but from being willing to sacrifice everything for those you call family. Together with their trusted key members',
    'about.legacy.p3.members': 'Aetherius, Valorius, Sanguis, Crimson, Aurelius, and Ignis',
    'about.legacy.p3.end': 'they have created a place where honor is earned through actions, not words—where loyalty is proven in the heat of battle, and where every member knows that their leaders would stand between them and danger without a second thought.',
    'about.legacy.p4': 'Under their guidance, Blood Paladins has become more than an alliance. It has become a brotherhood and sisterhood bound by unbreakable vows. Here, you will find warriors who will shield you with their own bodies, strategists who will share their knowledge without reservation, and leaders who will fight for your growth as fiercely as they fight for their own.',
    'about.legacy.p5': 'and their dedicated team have built something rare in this kingdom a place where honor is the currency, loyalty is the bond, and sacrifice is the ultimate expression of love for your family.',
    'about.legacy.p6': 'This is their legacy. This is Blood Paladins.',
    'about.leaders.title': 'Our Leaders',
    'about.leaders.pryda.name': 'Pryda',
    'about.leaders.pryda.role': 'Leader',
    'about.leaders.pryda.desc': 'A visionary strategist and unwavering commander, Pryda leads with wisdom and determination, guiding the family toward greatness with every decision.',
    'about.leaders.lundix.name': 'LundiX',
    'about.leaders.lundix.role': 'Co-Leader',
    'about.leaders.lundix.desc': 'A master tactician and trusted advisor, LundiX brings balance and strength to the leadership, ensuring every member thrives under their guidance.',
    'about.members.title': 'Key Members',
    'about.members.aetherius.role': 'Strategic Commander',
    'about.members.valorius.role': 'Battle Coordinator',
    'about.members.sanguis.role': 'Alliance Advisor',
    'about.members.crimson.role': 'Tactical Specialist',
    'about.members.aurelius.role': 'Recruitment Officer',
    'about.members.ignis.role': 'Training Master',
    'about.vision.title': 'Our Vision',
    'about.vision.quote': 'In a world where warriors fall forgotten and alliances crumble to dust, we dream of something',
    'about.vision.quote.eternal': 'eternal',
    'about.vision.quote.end': '.',
    'about.vision.p1': 'We envision a kingdom where the lonely find their family, where the broken find healing, and where the lost find their way home. A place where a new member\'s first day is met with open arms and genuine care, where their struggles become our struggles, and where their tears are met with understanding, not judgment.',
    'about.vision.p2': 'We see a future where Blood Paladins is not just remembered for battles won, but for',
    'about.vision.p2.lives': 'lives changed',
    'about.vision.p2.rest': '. Where a warrior who once felt worthless discovers their value. Where someone who never had a voice finds they matter. Where those who have been abandoned by others find they are finally, truly,',
    'about.vision.p2.loved': 'loved',
    'about.vision.p2.end': '.',
    'about.vision.p3': 'Our vision is simple: to be the family you\'ve been searching for, the home you\'ve been dreaming of, the bond that will never break.',
    'about.mission.title': 'Our Mission',
    'about.mission.p1': 'To stand as a shield for those who have none. To be the voice for those who have been silenced. To be the',
    'about.mission.p1.family': 'family',
    'about.mission.p1.end': 'for those who have been abandoned.',
    'about.mission.p2': 'When you join Blood Paladins, you are not joining an organization. You are coming home. You are finding the brothers and sisters you never knew you had. You are discovering that in this cold, unforgiving kingdom, there is a place where you matter where your pain is our pain, where your joy is our joy, where your dreams become our shared purpose.',
    'about.mission.p3': 'Our mission is to look into the eyes of every member and say, with absolute certainty:',
    'about.mission.p3.quote': 'You are not alone. You never will be again.',
    'about.mission.p3.rest': 'We will fight for you when you cannot fight for yourself. We will stand with you when the world stands against you. We will bleed for you, we will sacrifice for you, we will',
    'about.mission.p3.die': 'die for you',
    'about.mission.p3.end': 'because that is what family does.',
    'about.mission.p4': 'This is not about power. This is not about glory. This is about the warrior who joined us broken and left whole. The member who came to us lost and found their purpose. The person who thought they were worthless and discovered they were irreplaceable.',
    'about.mission.p5': 'We will build a legacy not of conquest, but of connection.',
    'about.mission.p6': 'Not of power, but of love. Not of victory, but of family.',
