    'main.alliance.members.title': 'Member Duties & Responsibilities',
    'main.alliance.member.active.title': 'Active Participation',
    'main.alliance.member.active.desc': 'Regular participation in alliance events, battles, and activities. Your presence and engagement strengthen our family. Attend scheduled events, respond to rally calls, and contribute to alliance goals.',
    'main.alliance.member.honor.title': 'Honor & Respect',
    'main.alliance.member.honor.desc': 'Treat every member with honor and respect. Uphold our values in all interactions, both within and outside the alliance. Show dignity to all warriors, regardless of their power or experience.',
    'main.alliance.member.loyalty.title': 'Loyalty & Commitment',
    'main.alliance.member.loyalty.desc': 'Remain loyal to Blood Paladins and committed to our shared goals. Stand with your family through victories and challenges. Your loyalty is the foundation of our strength.',
    'main.alliance.member.communication.title': 'Communication',
    'main.alliance.member.communication.desc': 'Maintain open communication with leaders and officers. Report issues, share ideas, and stay connected with the family. Keep leaders informed of your availability and any concerns.',
    'main.alliance.member.growth.title': 'Growth & Development',
    'main.alliance.member.growth.desc': 'Continuously work on improving your skills and power. Support fellow members in their growth journey. Help train new members and share knowledge with the family.',
    'main.alliance.member.sacrifice.title': 'Sacrifice & Support',
    'main.alliance.member.sacrifice.desc': 'Be willing to support your family members when needed. Remember: we fight together, we stand together, we die for each other. Put the family\'s needs above personal gain.',
    'main.alliance.member.resource.title': 'Resource Management',
    'main.alliance.member.resource.desc': 'Manage your resources wisely and contribute to alliance needs when possible. Support resource gathering efforts and share excess resources with members in need.',
    'main.alliance.member.battle.title': 'Battle Readiness',
    'main.alliance.member.battle.desc': 'Maintain your armies and commanders in battle-ready condition. Respond promptly to battle calls and follow strategic instructions during combat operations.',
