    'farms.title': 'Farm Alliances',
    'farms.description.p1': 'Our',
    'farms.description.p1.farms': 'Farm Alliances',
    'farms.description.p1.end': 'are the backbone of our family\'s resource network. These alliances provide essential support to the main alliance through strategic resource gathering and positioning.',
    'farms.description.p2': 'Every member of Blood Paladins can send their farms to one of our farm alliances. This allows for organized resource management, strategic positioning, and ensures that our main alliance members can focus on battles and events while farms are safely managed and productive.',
