    'join.main.who.item4': 'Those who have completed Academy training',
    'join.main.who.item5': 'Warriors seeking the ultimate family bond',
    'join.academy.title': 'Paladins Academy',
    'join.academy.subtitle': 'Training Ground',
    'join.academy.about.title': 'About Paladins Academy',
    'join.academy.about.p1': 'The training ground where new warriors begin their journey with Blood Paladins. Paladins Academy is designed for members who are learning the fundamentals, developing their skills, and preparing for advancement to the main alliance.',
    'join.academy.about.p2': 'Under the guidance of experienced leaders and officers, Academy members receive personalized training, mentorship, and support as they grow into elite warriors worthy of joining Blood Paladins Main Alliance. This is where your journey begins, where you learn what it means to be a Blood Paladin.',
    'join.academy.offer.title': 'What We Offer:',
    'join.academy.offer.item1': 'Personalized training and mentorship programs',
    'join.academy.offer.item2': 'Clear progression path to Main Alliance',
