    'join.academy.who.item4': 'Players preparing for Main Alliance',
    'join.academy.who.item5': 'Anyone wanting to learn Blood Paladins values',
    'join.farms.title': 'Farm Alliances',
    'join.farms.subtitle': 'Resource Network',
    'join.farms.about.title': 'About Our Farm Alliances',
    'join.farms.about.p1': 'Our Farm Alliances (Paladins Farm1, Farm2, and Farm3) are the backbone of our family\'s resource network. These alliances provide essential support to the main alliance through strategic resource gathering and positioning.',
    'join.farms.about.p2': 'Every member of Blood Paladins can send their farms to one of our farm alliances. This allows for organized resource management, strategic positioning, and ensures that our main alliance members can focus on battles and events while farms are safely managed and productive. Beyond resource gathering, our farm alliances serve a crucial strategic role as CF Bombs during KVK events and other major operations.',
    'join.farms.offer.title': 'What We Offer:',
    'join.farms.offer.item1': 'Organized resource gathering and management',
    'join.farms.offer.item2': 'Strategic territory positioning',
    'join.farms.offer.item3': 'Safe and protected farm accounts',
