    'join.contact.description': 'Contact us through Telegram or Discord to start your application process.',
    'join.contact.details': 'Tell us about yourself, your power level, which alliance you\'re interested in joining, and why you want to become part of the Blood Paladins family. We\'re waiting to welcome you home.',
    'join.contact.discord': 'Join on Discord',
    'join.contact.telegram': 'Join on Telegram',
    'footer.brand.description': 'The Strongest Family in the Kingdom. Join us and become part of a true brotherhood bound by honor, loyalty, and unbreakable unity.',
