    'main.alliance.member.active.title': '积极参与',
    'main.alliance.member.active.desc': '定期参与联盟活动、战斗和事务。您的存在和参与加强了我们的家族。参加预定活动，响应集结号召，并为联盟目标做出贡献。',
    'main.alliance.member.honor.title': '荣誉与尊重',
    'main.alliance.member.honor.desc': '以荣誉和尊重对待每个成员。在所有互动中，无论是在联盟内部还是外部，都要维护我们的价值观。对所有战士表现出尊严，无论他们的力量或经验如何。',
    'main.alliance.member.loyalty.title': '忠诚与承诺',
    'main.alliance.member.loyalty.desc': '保持对血骑士的忠诚，并致力于我们的共同目标。在胜利和挑战中与您的家人站在一起。您的忠诚是我们力量的基础。',
    'main.alliance.member.communication.title': '沟通',
    'main.alliance.member.communication.desc': '与领导者和军官保持开放的沟通。报告问题，分享想法，并与家人保持联系。让领导者了解您的可用性和任何担忧。',
    'main.alliance.member.growth.title': '成长与发展',
    'main.alliance.member.growth.desc': '持续努力提高您的技能和力量。支持其他成员的成长之旅。帮助训练新成员并与家人分享知识。',
    'main.alliance.member.sacrifice.title': '牺牲与支持',
    'main.alliance.member.sacrifice.desc': '在需要时愿意支持您的家人。记住：我们一起战斗，我们站在一起，我们为彼此而死。将家庭的需求置于个人利益之上。',
    'main.alliance.member.resource.title': '资源管理',
    'main.alliance.member.resource.desc': '明智地管理您的资源，并在可能的情况下为联盟需求做出贡献。支持资源收集工作，并与有需要的成员分享多余资源。',
    'main.alliance.member.battle.title': '战斗准备',
    'main.alliance.member.battle.desc': '保持您的军队和指挥官处于战斗就绪状态。及时响应战斗号召，并在战斗行动中遵循战略指示。',
