    'farms.title': '农场联盟',
    'farms.description.p1': '我们的',
    'farms.description.p1.farms': '农场联盟',
    'farms.description.p1.end': '是我们家族资源网络的支柱。这些联盟通过战略资源收集和定位为主要联盟提供重要支持。',
    'farms.description.p2': '血骑士的每个成员都可以将他们的农场发送到我们的一个农场联盟。这允许有组织的资源管理、战略定位，并确保我们的主联盟成员可以专注于战斗和活动，而农场得到安全管理和生产。',
