    'farms.description.p3.kvk': 'KVK（王国对王国）',
    'farms.description.p3.end': '活动和其他主要行动中发挥关键战略作用。这些农场在家族最需要的时候提供重要的战术支持、战略定位和操作灵活性。',
    'farms.purpose': '目的：',
