    'farms.farm3.benefit5': '完整的运营网络',
    'farms.how.title': '工作原理',
    'farms.how.step1.title': '发送您的农场',
    'farms.how.step1.desc': '作为血骑士的成员，您可以将您的农场账户发送到我们的一个农场联盟。这有助于组织我们的资源网络，并保持农场活跃和生产。',
    'farms.how.step2.title': '有组织的管理',
    'farms.how.step2.desc': '农场联盟由专门的军官管理，他们确保农场活跃、收集资源，并为家族的整体实力和战略定位做出贡献。',
    'farms.how.step3.title': '战略支持与CF炸弹',
    'farms.how.step3.desc': '通过在专门的联盟中拥有农场，主联盟成员可以专注于战斗和活动，而农场提供重要的资源支持和战略定位。在KVK和主要行动期间，这些农场作为',
