    'join.academy.about.title': '关于Paladins Academy',
    'join.academy.about.p1': '新战士开始与血骑士一起旅程的训练场。Paladins Academy专为正在学习基础知识、发展技能并为晋升到主联盟做准备的成员而设计。',
    'join.academy.about.p2': '在经验丰富的领导者和军官的指导下，学院成员接受个性化培训、指导和支助，成长为值得加入血骑士主联盟的精英战士。这是您旅程开始的地方，在这里您学习成为血骑士意味着什么。',
    'join.academy.offer.title': '我们提供：',
