    'join.farms.title': '农场联盟',
    'join.farms.subtitle': '资源网络',
    'join.farms.about.title': '关于我们的农场联盟',
    'join.farms.about.p1': '我们的农场联盟（Paladins Farm1、Farm2和Farm3）是我们家族资源网络的支柱。这些联盟通过战略资源收集和定位为主要联盟提供重要支持。',
    'join.farms.about.p2': '血骑士的每个成员都可以将他们的农场发送到我们的一个农场联盟。这允许有组织的资源管理、战略定位，并确保我们的主联盟成员可以专注于战斗和活动，而农场得到安全管理和生产。除了资源收集，我们的农场联盟还在KVK活动和其他主要行动中作为CF炸弹发挥关键战略作用。',
    'join.farms.offer.title': '我们提供：',
