    'join.contact.description': '通过Telegram或Discord联系我们开始您的申请流程。',
    'join.contact.details': '告诉我们关于您自己、您的力量水平、您感兴趣的联盟，以及为什么您想成为血骑士家族的一员。我们等待欢迎您回家。',
    'join.contact.discord': '在Discord上加入',
    'join.contact.telegram': '在Telegram上加入',
    'footer.brand.description': '王国中最强大的家族。加入我们，成为由荣誉、忠诚和不可打破的团结所约束的真正兄弟会的一部分。',
    'footer.brand.quote': '在血骑士中，我们不仅仅是一起战斗。我们为彼此而死。',
