    'main.alliance.officer.aetherius.duty2': 'Phối hợp nỗ lực chiến tranh',
    'main.alliance.officer.aetherius.duty3': 'Phân tích chuyển động của kẻ thù',
    'main.alliance.officer.aetherius.duty4': 'Lập kế hoạch hoạt động chiến thuật',
