    'main.alliance.members.title': 'Nhiệm Vụ & Trách Nhiệm Thành Viên',
    'main.alliance.member.active.title': 'Tham Gia Tích Cực',
    'main.alliance.member.active.desc': 'Tham gia thường xuyên vào các sự kiện, trận chiến và hoạt động của liên minh. Sự hiện diện và tham gia của bạn củng cố gia đình chúng ta. Tham dự các sự kiện đã lên lịch, phản hồi các lời kêu gọi tập hợp, và đóng góp cho các mục tiêu liên minh.',
    'main.alliance.member.honor.title': 'Danh Dự & Tôn Trọng',
    'main.alliance.member.honor.desc': 'Đối xử với mọi thành viên bằng danh dự và tôn trọng. Duy trì các giá trị của chúng ta trong tất cả các tương tác, cả trong và ngoài liên minh. Thể hiện phẩm giá với tất cả các chiến binh, bất kể sức mạnh hay kinh nghiệm của họ.',
    'main.alliance.member.loyalty.title': 'Lòng Trung Thành & Cam Kết',
    'main.alliance.member.loyalty.desc': 'Giữ lòng trung thành với Blood Paladins và cam kết với các mục tiêu chung của chúng ta. Đứng cùng gia đình của bạn qua những chiến thắng và thử thách. Lòng trung thành của bạn là nền tảng của sức mạnh chúng ta.',
    'main.alliance.member.communication.title': 'Giao Tiếp',
    'main.alliance.member.communication.desc': 'Duy trì giao tiếp cởi mở với các nhà lãnh đạo và sĩ quan. Báo cáo vấn đề, chia sẻ ý tưởng, và giữ liên lạc với gia đình. Thông báo cho các nhà lãnh đạo về tình trạng sẵn sàng của bạn và bất kỳ mối quan ngại nào.',
    'main.alliance.member.growth.title': 'Tăng Trưởng & Phát Triển',
    'main.alliance.member.growth.desc': 'Liên tục làm việc để cải thiện kỹ năng và sức mạnh của bạn. Hỗ trợ các thành viên khác trong hành trình phát triển của họ. Giúp đào tạo thành viên mới và chia sẻ kiến thức với gia đình.',
    'main.alliance.member.sacrifice.title': 'Hy Sinh & Hỗ Trợ',
    'main.alliance.member.sacrifice.desc': 'Sẵn sàng hỗ trợ các thành viên gia đình khi cần. Nhớ rằng: chúng ta chiến đấu cùng nhau, chúng ta đứng cùng nhau, chúng ta chết vì nhau. Đặt nhu cầu của gia đình lên trên lợi ích cá nhân.',
    'main.alliance.member.resource.title': 'Quản Lý Tài Nguyên',
    'main.alliance.member.resource.desc': 'Quản lý tài nguyên của bạn một cách khôn ngoan và đóng góp cho nhu cầu liên minh khi có thể. Hỗ trợ nỗ lực thu thập tài nguyên và chia sẻ tài nguyên dư thừa với các thành viên đang cần.',
    'main.alliance.member.battle.title': 'Sẵn Sàng Chiến Đấu',
    'main.alliance.member.battle.desc': 'Duy trì quân đội và chỉ huy của bạn trong tình trạng sẵn sàng chiến đấu. Phản hồi kịp thời các lời kêu gọi chiến đấu và tuân theo hướng dẫn chiến lược trong các hoạt động chiến đấu.',
    'academy.title': 'Paladins Academy',
    'academy.description.p1': 'Nơi',
    'academy.description.p1.training': 'huấn luyện',
    'academy.description.p1.end': 'nơi các chiến binh mới bắt đầu hành trình của họ với Blood Paladins. Tại đây, các thành viên học những điều cơ bản, phát triển kỹ năng và chuẩn bị để thăng tiến lên liên minh chính.',
    'academy.description.p2': 'Dưới sự hướng dẫn của các nhà lãnh đạo và sĩ quan giàu kinh nghiệm, các thành viên Academy nhận được đào tạo cá nhân hóa, cố vấn và hỗ trợ khi họ phát triển thành các chiến binh tinh nhuệ xứng đáng tham gia Blood Paladins Liên Minh Chính.',
