    'main.alliance.overview.p1.end': '। यह वह जगह है जहाँ हमारे सबसे अनुभवी योद्धा, रणनीतिक दिमाग, और समर्पित नेता एक अटूट बल बनाने के लिए एकजुट होते हैं।',
    'main.alliance.overview.p2': 'Blood Paladins मुख्य गठबंधन हमारे परिवार की ताकत का शिखर है—सम्मान, निष्ठा और उत्कृष्टता के प्रति अटूट प्रतिबद्धता से बंधे अभिजात वर्ग के योद्धाओं का भाईचारा। यहाँ, हर सदस्य एक रक्षक है, हर अधिकारी एक संरक्षक है, और हर निर्णय परिवार के भविष्य को ध्यान में रखकर लिया जाता है।',
