    'main.alliance.members.title': 'सदस्य कर्तव्य और जिम्मेदारियाँ',
    'main.alliance.member.active.title': 'सक्रिय भागीदारी',
    'main.alliance.member.active.desc': 'गठबंधन कार्यक्रमों, युद्धों और गतिविधियों में नियमित भागीदारी। आपकी उपस्थिति और जुड़ाव हमारे परिवार को मजबूत करता है। निर्धारित कार्यक्रमों में भाग लें, रैली कॉल का जवाब दें, और गठबंधन लक्ष्यों में योगदान करें।',
    'main.alliance.member.honor.title': 'सम्मान और सम्मान',
    'main.alliance.member.honor.desc': 'हर सदस्य के साथ सम्मान और सम्मान के साथ व्यवहार करें। सभी बातचीत में, गठबंधन के भीतर और बाहर दोनों में, हमारे मूल्यों को बनाए रखें। सभी योद्धाओं के प्रति गरिमा दिखाएं, चाहे उनकी शक्ति या अनुभव कुछ भी हो।',
    'main.alliance.member.loyalty.title': 'निष्ठा और प्रतिबद्धता',
    'main.alliance.member.loyalty.desc': 'Blood Paladins के प्रति वफादार रहें और हमारे साझा लक्ष्यों के प्रति प्रतिबद्ध रहें। जीत और चुनौतियों में अपने परिवार के साथ खड़े हों। आपकी निष्ठा हमारी ताकत की नींव है।',
    'main.alliance.member.communication.title': 'संचार',
    'main.alliance.member.communication.desc': 'नेताओं और अधिकारियों के साथ खुला संचार बनाए रखें। समस्याओं की रिपोर्ट करें, विचार साझा करें, और परिवार के साथ जुड़े रहें। नेताओं को अपनी उपलब्धता और किसी भी चिंता के बारे में सूचित रखें।',
    'main.alliance.member.growth.title': 'वृद्धि और विकास',
    'main.alliance.member.growth.desc': 'अपने कौशल और शक्ति में सुधार के लिए लगातार काम करें। अन्य सदस्यों की वृद्धि यात्रा में समर्थन करें। नए सदस्यों को प्रशिक्षित करने में मदद करें और परिवार के साथ ज्ञान साझा करें।',
    'main.alliance.member.sacrifice.title': 'बलिदान और समर्थन',
    'main.alliance.member.sacrifice.desc': 'जरूरत पड़ने पर अपने परिवार के सदस्यों का समर्थन करने के लिए तैयार रहें। याद रखें: हम एक साथ लड़ते हैं, हम एक साथ खड़े होते हैं, हम एक दूसरे के लिए मरते हैं। परिवार की जरूरतों को व्यक्तिगत लाभ से ऊपर रखें।',
    'main.alliance.member.resource.title': 'संसाधन प्रबंधन',
    'main.alliance.member.resource.desc': 'अपने संसाधनों का बुद्धिमानी से प्रबंधन करें और जब संभव हो तो गठबंधन की जरूरतों में योगदान करें। संसाधन एकत्र करने के प्रयासों का समर्थन करें और जरूरतमंद सदस्यों के साथ अतिरिक्त संसाधन साझा करें।',
    'main.alliance.member.battle.title': 'युद्ध की तैयारी',
    'main.alliance.member.battle.desc': 'अपनी सेनाओं और कमांडरों को युद्ध के लिए तैयार स्थिति में रखें। युद्ध कॉल का तुरंत जवाब दें और लड़ाई के संचालन के दौरान रणनीतिक निर्देशों का पालन करें।',
    'academy.title': 'Paladins Academy',
    'academy.description.p1': 'वह',
    'academy.description.p1.training': 'प्रशिक्षण स्थल',
    'academy.description.p1.end': 'जहाँ नए योद्धा Blood Paladins के साथ अपनी यात्रा शुरू करते हैं। यहाँ, सदस्य मूल बातें सीखते हैं, अपने कौशल विकसित करते हैं, और मुख्य गठबंधन में प्रगति के लिए तैयार होते हैं।',
    'academy.description.p2': 'अनुभवी नेताओं और अधिकारियों के मार्गदर्शन में, Academy सदस्य व्यक्तिगत प्रशिक्षण, सलाह और समर्थन प्राप्त करते हैं क्योंकि वे Blood Paladins मुख्य गठबंधन में शामिल होने के योग्य अभिजात वर्ग के योद्धाओं में विकसित होते हैं।',
