    'farms.title': 'फार्म गठबंधन',
    'farms.description.p1': 'हमारे',
    'farms.description.p1.farms': 'फार्म गठबंधन',
    'farms.description.p1.end': 'हमारे परिवार के संसाधन नेटवर्क की रीढ़ हैं। ये गठबंधन रणनीतिक संसाधन संग्रह और स्थिति के माध्यम से मुख्य गठबंधन को आवश्यक समर्थन प्रदान करते हैं।',
    'farms.description.p2': 'Blood Paladins के प्रत्येक सदस्य अपने फार्म को हमारे एक फार्म गठबंधन में भेज सकते हैं। यह संगठित संसाधन प्रबंधन, रणनीतिक स्थिति की अनुमति देता है, और सुनिश्चित करता है कि हमारे मुख्य गठबंधन सदस्य लड़ाई और कार्यक्रमों पर ध्यान केंद्रित कर सकें जबकि फार्म सुरक्षित रूप से प्रबंधित और उत्पादक हैं।',
    'farms.description.p3': 'संसाधन संग्रह के अलावा, हमारे फार्म गठबंधन',
    'farms.description.p3.cf': 'CF बम',
    'farms.description.p3.during': 'के दौरान',
    'farms.description.p3.kvk': 'KVK (राज्य बनाम राज्य)',
    'farms.description.p3.end': 'कार्यक्रमों और अन्य प्रमुख संचालनों में महत्वपूर्ण रणनीतिक भूमिका निभाते हैं। ये फार्म आवश्यक सामरिक समर्थन, रणनीतिक स्थिति, और परिचालन लचीलापन प्रदान करते हैं जब परिवार को उनकी सबसे अधिक आवश्यकता होती है।',
    'farms.purpose': 'उद्देश्य:',
    'farms.benefits': 'लाभ:',
    'farms.farm1.name': 'Paladins Farm1',
    'farms.farm1.role': 'प्राथमिक फार्म गठबंधन',
    'farms.farm1.purpose': 'Blood Paladins के लिए प्राथमिक संसाधन संग्रह गठबंधन। कुशल संसाधन संग्रह, रणनीतिक स्थिति पर केंद्रित, और KVK संचालन के लिए CF बम के रूप में कार्य करता है।',
    'farms.farm1.benefit1': 'संगठित संसाधन प्रबंधन',
    'farms.farm1.benefit2': 'रणनीतिक क्षेत्र स्थिति',
    'farms.farm1.benefit3': 'KVK के लिए CF बम संचालन',
    'farms.farm1.benefit4': 'सक्रिय संसाधन संग्रह',
    'farms.farm1.benefit5': 'मुख्य गठबंधन के लिए सामरिक समर्थन',
    'farms.farm2.name': 'Paladins Farm2',
    'farms.farm2.role': 'द्वितीयक फार्म गठबंधन',
    'farms.farm2.purpose': 'Farm1 को पूरक करने वाला द्वितीयक समर्थन गठबंधन। अतिरिक्त संसाधन क्षमता, रणनीतिक लचीलापन, और प्रमुख संचालनों के लिए CF बम क्षमता प्रदान करता है।',
    'farms.farm2.benefit1': 'अतिरिक्त संसाधन क्षमता',
    'farms.farm2.benefit2': 'संचालनों के लिए CF बम समर्थन',
