    'farms.farm2.benefit4': 'लचीला संसाधन आवंटन',
    'farms.farm2.benefit5': 'सामरिक अतिरेक और सुरक्षा',
    'farms.farm3.name': 'Paladins Farm3',
    'farms.farm3.role': 'अतिरिक्त फार्म गठबंधन',
    'farms.farm3.purpose': 'विस्तारित संसाधन नेटवर्क के लिए अतिरिक्त फार्म गठबंधन। अधिकतम संसाधन संग्रह क्षमता सुनिश्चित करता है और बड़े पैमाने के संचालनों के लिए अतिरिक्त CF बम क्षमता प्रदान करता है।',
    'farms.farm3.benefit1': 'अधिकतम संसाधन क्षमता',
    'farms.farm3.benefit2': 'CF बम संचालन समर्थन',
    'farms.farm3.benefit3': 'विस्तारित नेटवर्क कवरेज',
    'farms.farm3.benefit4': 'वर्धित रणनीतिक विकल्प',
    'farms.farm3.benefit5': 'पूर्ण परिचालन नेटवर्क',
    'farms.how.title': 'यह कैसे काम करता है',
    'farms.how.step1.title': 'अपने फार्म भेजें',
    'farms.how.step1.desc': 'Blood Paladins के सदस्य के रूप में, आप अपने फार्म खातों को हमारे एक फार्म गठबंधन में भेज सकते हैं। यह हमारे संसाधन नेटवर्क को व्यवस्थित करने में मदद करता है और फार्म को सक्रिय और उत्पादक रखता है।',
    'farms.how.step2.title': 'संगठित प्रबंधन',
    'farms.how.step2.desc': 'फार्म गठबंधन समर्पित अधिकारियों द्वारा प्रबंधित किए जाते हैं जो सुनिश्चित करते हैं कि फार्म सक्रिय हैं, संसाधन एकत्र कर रहे हैं, और परिवार की समग्र ताकत और रणनीतिक स्थिति में योगदान दे रहे हैं।',
    'farms.how.step3.title': 'रणनीतिक समर्थन और CF बम',
    'farms.how.step3.desc': 'समर्पित गठबंधनों में फार्म होने से, मुख्य गठबंधन सदस्य लड़ाई और कार्यक्रमों पर ध्यान केंद्रित कर सकते हैं जबकि फार्म आवश्यक संसाधन समर्थन और रणनीतिक स्थिति प्रदान करते हैं। KVK और प्रमुख संचालनों के दौरान, ये फार्म',
    'farms.how.step3.cf': 'CF बम',
    'farms.how.step3.end': 'के रूप में कार्य करते हैं—महत्वपूर्ण सामरिक संपत्ति जो रणनीतिक लाभ और परिचालन लचीलापन प्रदान करती है जब हमें उनकी सबसे अधिक आवश्यकता होती है।',
