    'kingdom.info.p1.end': 'में काम करते हैं—एक',
    'kingdom.info.p1.strong': 'मजबूत और स्थिर राज्य',
    'kingdom.info.p1.rest': 'जहाँ रणनीति, संगठन और टीम वर्क जीत की ओर ले जाते हैं। हमारा राज्य विकास, प्रभुत्व और स्थायी गठबंधन बनाने के लिए सही वातावरण प्रदान करता है।',
    'kingdom.info.p2': 'से अधिक',
    'kingdom.info.p2.power': 'कुल शक्ति और',
    'kingdom.info.p2.alliances': 'सक्रिय गठबंधन के साथ, यह राज्य अपने संगठित नेतृत्व, सक्रिय समुदाय, रणनीतिक क्षेत्र नियंत्रण, और एक मजबूत गठबंधन नेटवर्क के लिए जाना जाता है जो आपसी सफलता के लिए एक साथ काम करता है। यह एक ऐसा राज्य है जहाँ सम्मान, निष्ठा और उत्कृष्टता सिर्फ शब्द नहीं हैं—वे हर चीज की नींव हैं जो हम करते हैं।',
    'kingdom.rules.title': 'राज्य नियम और दिशानिर्देश',
