    'join.academy.who.item2': 'अपने कौशल में सुधार करना चाहने वाले खिलाड़ी',
    'join.academy.who.item3': 'सलाह और मार्गदर्शन चाहने वाले',
    'join.academy.who.item4': 'मुख्य गठबंधन के लिए तैयारी करने वाले खिलाड़ी',
    'join.academy.who.item5': 'कोई भी जो Blood Paladins मूल्यों को सीखना चाहता है',
    'join.farms.title': 'फार्म गठबंधन',
    'join.farms.subtitle': 'संसाधन नेटवर्क',
    'join.farms.about.title': 'हमारे फार्म गठबंधन के बारे में',
    'join.farms.about.p1': 'हमारे फार्म गठबंधन (Paladins Farm1, Farm2 और Farm3) हमारे परिवार के संसाधन नेटवर्क की रीढ़ हैं। ये गठबंधन रणनीतिक संसाधन संग्रह और स्थिति के माध्यम से मुख्य गठबंधन को आवश्यक समर्थन प्रदान करते हैं।',
    'join.farms.about.p2': 'Blood Paladins के प्रत्येक सदस्य अपने फार्म को हमारे एक फार्म गठबंधन में भेज सकते हैं। यह संगठित संसाधन प्रबंधन, रणनीतिक स्थिति की अनुमति देता है, और सुनिश्चित करता है कि हमारे मुख्य गठबंधन सदस्य लड़ाई और कार्यक्रमों पर ध्यान केंद्रित कर सकें जबकि फार्म सुरक्षित रूप से प्रबंधित और उत्पादक हैं। संसाधन संग्रह के अलावा, हमारे फार्म गठबंधन KVK कार्यक्रमों और अन्य प्रमुख संचालनों के दौरान CF बम के रूप में महत्वपूर्ण रणनीतिक भूमिका निभाते हैं।',
    'join.farms.offer.title': 'हम क्या प्रदान करते हैं:',
    'join.farms.offer.item1': 'संगठित संसाधन संग्रह और प्रबंधन',
    'join.farms.offer.item2': 'रणनीतिक क्षेत्र स्थिति',
