    'join.farms.who.item5': 'कोई भी जो परिवार के संसाधन नेटवर्क का समर्थन करता है',
    'join.contact.title': 'शामिल होने के लिए तैयार?',
    'join.contact.description': 'अपनी आवेदन प्रक्रिया शुरू करने के लिए Telegram या Discord के माध्यम से हमसे संपर्क करें।',
    'join.contact.details': 'हमें अपने बारे में, अपने शक्ति स्तर, जिस गठबंधन में आप शामिल होना चाहते हैं, और आप Blood Paladins परिवार का हिस्सा क्यों बनना चाहते हैं, के बारे में बताएं। हम आपका घर पर स्वागत करने के लिए इंतजार कर रहे हैं।',
