    'main.alliance.officer.guardian.duty5': 'Реагирует на чрезвычайные ситуации',
    'main.alliance.members.title': 'Обязанности и Ответственность Членов',
    'main.alliance.member.active.title': 'Активное Участие',
    'main.alliance.member.active.desc': 'Регулярное участие в событиях альянса, битвах и мероприятиях. Ваше присутствие и вовлеченность укрепляют нашу семью. Посещайте запланированные события, отвечайте на призывы к сбору и вносите вклад в цели альянса.',
    'main.alliance.member.honor.title': 'Честь и Уважение',
    'main.alliance.member.honor.desc': 'Относитесь к каждому члену с честью и уважением. Поддерживайте наши ценности во всех взаимодействиях, как внутри, так и вне альянса. Проявляйте достоинство ко всем воинам, независимо от их силы или опыта.',
    'main.alliance.member.loyalty.title': 'Верность и Преданность',
    'main.alliance.member.loyalty.desc': 'Оставайтесь верными Кровавым Паладинам и преданными нашим общим целям. Стойте со своей семьей через победы и вызовы. Ваша верность—основа нашей силы.',
    'main.alliance.member.communication.title': 'Коммуникация',
    'main.alliance.member.communication.desc': 'Поддерживайте открытое общение с лидерами и офицерами. Сообщайте о проблемах, делитесь идеями и оставайтесь на связи с семьей. Информируйте лидеров о своей доступности и любых проблемах.',
    'main.alliance.member.growth.title': 'Рост и Развитие',
    'main.alliance.member.growth.desc': 'Постоянно работайте над улучшением своих навыков и силы. Поддерживайте других членов в их пути роста. Помогайте обучать новых членов и делитесь знаниями с семьей.',
    'main.alliance.member.sacrifice.title': 'Жертва и Поддержка',
    'main.alliance.member.sacrifice.desc': 'Будьте готовы поддержать членов вашей семьи, когда это необходимо. Помните: мы сражаемся вместе, мы стоим вместе, мы умираем друг за друга. Ставьте потребности семьи выше личной выгоды.',
    'main.alliance.member.resource.title': 'Управление Ресурсами',
    'main.alliance.member.resource.desc': 'Управляйте своими ресурсами мудро и вносите вклад в потребности альянса, когда это возможно. Поддерживайте усилия по сбору ресурсов и делитесь избыточными ресурсами с нуждающимися членами.',
    'main.alliance.member.battle.title': 'Боевая Готовность',
    'main.alliance.member.battle.desc': 'Поддерживайте свои армии и командиров в боеготовом состоянии. Быстро реагируйте на боевые призывы и следуйте стратегическим инструкциям во время боевых операций.',
    'academy.title': 'Академия Паладинов',
    'academy.description.p1': 'Поле',
    'academy.description.p1.training': 'тренировок',
    'academy.description.p1.end': 'где новые воины начинают свой путь с Кровавыми Паладинами. Здесь члены изучают основы, развивают свои навыки и готовятся к продвижению в главный альянс.',
    'academy.description.p2': 'Под руководством опытных лидеров и офицеров члены Академии получают персонализированное обучение, наставничество и поддержку, развиваясь в элитных воинов, достойных присоединения к Главному Альянсу Кровавых Паладинов.',
