    'main.alliance.members.title': 'Deberes y Responsabilidades de Miembros',
    'main.alliance.member.active.title': 'Participación Activa',
    'main.alliance.member.active.desc': 'Participación regular en eventos, batallas y actividades de la alianza. Tu presencia y compromiso fortalecen nuestra familia. Asiste a eventos programados, responde a llamadas de reunión y contribuye a los objetivos de la alianza.',
    'main.alliance.member.honor.title': 'Honor y Respeto',
    'main.alliance.member.honor.desc': 'Trata a cada miembro con honor y respeto. Mantén nuestros valores en todas las interacciones, tanto dentro como fuera de la alianza. Muestra dignidad a todos los guerreros, independientemente de su poder o experiencia.',
    'main.alliance.member.loyalty.title': 'Lealtad y Compromiso',
    'main.alliance.member.loyalty.desc': 'Mantén lealtad a Blood Paladins y compromiso con nuestros objetivos compartidos. Quédate con tu familia a través de victorias y desafíos. Tu lealtad es la base de nuestra fuerza.',
    'main.alliance.member.communication.title': 'Comunicación',
    'main.alliance.member.communication.desc': 'Mantén comunicación abierta con líderes y oficiales. Reporta problemas, comparte ideas y mantente conectado con la familia. Mantén a los líderes informados de tu disponibilidad y cualquier preocupación.',
    'main.alliance.member.growth.title': 'Crecimiento y Desarrollo',
    'main.alliance.member.growth.desc': 'Trabaja continuamente en mejorar tus habilidades y poder. Apoya a otros miembros en su viaje de crecimiento. Ayuda a entrenar nuevos miembros y comparte conocimiento con la familia.',
    'main.alliance.member.sacrifice.title': 'Sacrificio y Apoyo',
    'main.alliance.member.sacrifice.desc': 'Está dispuesto a apoyar a los miembros de tu familia cuando sea necesario. Recuerda: luchamos juntos, nos mantenemos juntos, morimos el uno por el otro. Pon las necesidades de la familia por encima de la ganancia personal.',
    'main.alliance.member.resource.title': 'Gestión de Recursos',
    'main.alliance.member.resource.desc': 'Gestiona tus recursos sabiamente y contribuye a las necesidades de la alianza cuando sea posible. Apoya los esfuerzos de recolección de recursos y comparte recursos excedentes con miembros necesitados.',
    'main.alliance.member.battle.title': 'Preparación para la Batalla',
    'main.alliance.member.battle.desc': 'Mantén tus ejércitos y comandantes en condición lista para la batalla. Responde rápidamente a las llamadas de batalla y sigue las instrucciones estratégicas durante las operaciones de combate.',
    'academy.title': 'Academia Paladins',
    'academy.description.p1': 'El',
    'academy.description.p1.training': 'campo de entrenamiento',
    'academy.description.p1.end': 'donde los nuevos guerreros comienzan su viaje con Blood Paladins. Aquí, los miembros aprenden los fundamentos, desarrollan sus habilidades y se preparan para avanzar a la alianza principal.',
    'academy.description.p2': 'Bajo la guía de líderes y oficiales experimentados, los miembros de la Academia reciben entrenamiento personalizado, mentoría y apoyo mientras crecen en guerreros de élite dignos de unirse a la Alianza Principal de Blood Paladins.',
