    'farms.title': 'Alianzas de Granjas',
    'farms.description.p1': 'Nuestras',
    'farms.description.p1.farms': 'Alianzas de Granjas',
    'farms.description.p1.end': 'son la columna vertebral de la red de recursos de nuestra familia. Estas alianzas proporcionan apoyo esencial a la alianza principal a través de la recolección estratégica de recursos y posicionamiento.',
    'farms.description.p2': 'Cada miembro de Blood Paladins puede enviar sus granjas a una de nuestras alianzas de granjas. Esto permite una gestión organizada de recursos, posicionamiento estratégico y asegura que los miembros de la alianza principal puedan enfocarse en batallas y eventos mientras las granjas se gestionan de manera segura y productiva.',
    'farms.description.p3': 'Más allá de la recolección de recursos, nuestras alianzas de granjas sirven un papel estratégico crucial como',
    'farms.description.p3.cf': 'CF Bombs',
    'farms.description.p3.during': 'durante',
    'farms.description.p3.kvk': 'KVK (Reino vs Reino)',
    'farms.description.p3.end': 'eventos y otras operaciones importantes. Estas granjas proporcionan apoyo táctico esencial, posicionamiento estratégico y flexibilidad operativa cuando la familia más los necesita.',
    'farms.purpose': 'Propósito:',
    'farms.benefits': 'Beneficios:',
    'farms.farm1.name': 'Paladins Farm1',
    'farms.farm1.role': 'Alianza de Granja Principal',
    'farms.farm1.purpose': 'La alianza principal de recolección de recursos para Blood Paladins. Se enfoca en la recolección eficiente de recursos, posicionamiento estratégico y sirve como CF Bombs para operaciones KVK.',
    'farms.farm1.benefit1': 'Gestión organizada de recursos',
    'farms.farm1.benefit2': 'Posicionamiento estratégico de territorio',
    'farms.farm1.benefit3': 'Operaciones CF Bomb para KVK',
    'farms.farm1.benefit4': 'Recolección activa de recursos',
    'farms.farm1.benefit5': 'Apoyo táctico para la alianza principal',
    'farms.farm2.name': 'Paladins Farm2',
    'farms.farm2.role': 'Alianza de Granja Secundaria',
    'farms.farm2.purpose': 'Alianza de apoyo secundaria que complementa Farm1. Proporciona capacidad adicional de recursos, flexibilidad estratégica y capacidades CF Bomb para operaciones importantes.',
    'farms.farm2.benefit1': 'Capacidad adicional de recursos',
    'farms.farm2.benefit2': 'Apoyo CF Bomb para operaciones',
    'farms.farm2.benefit3': 'Posicionamiento estratégico de respaldo',
    'farms.farm2.benefit4': 'Asignación flexible de recursos',
    'farms.farm2.benefit5': 'Redundancia y seguridad táctica',
    'farms.farm3.name': 'Paladins Farm3',
    'farms.farm3.role': 'Alianza de Granja Adicional',
    'farms.farm3.purpose': 'Alianza de granja adicional para red de recursos expandida. Asegura capacidad máxima de recolección de recursos y proporciona capacidades CF Bomb adicionales para operaciones a gran escala.',
    'farms.farm3.benefit1': 'Capacidad máxima de recursos',
    'farms.farm3.benefit2': 'Apoyo de operaciones CF Bomb',
    'farms.farm3.benefit3': 'Cobertura de red extendida',
    'farms.farm3.benefit4': 'Opciones estratégicas mejoradas',
    'farms.farm3.benefit5': 'Red operativa completa',
    'farms.how.title': 'Cómo Funciona',
    'farms.how.step1.title': 'Envía Tus Granjas',
    'farms.how.step1.desc': 'Como miembro de Blood Paladins, puedes enviar tus cuentas de granja a una de nuestras alianzas de granjas. Esto ayuda a organizar nuestra red de recursos y mantiene las granjas activas y productivas.',
    'farms.how.step2.title': 'Gestión Organizada',
    'farms.how.step2.desc': 'Las alianzas de granjas son gestionadas por oficiales dedicados que aseguran que las granjas estén activas, recolectando recursos y contribuyendo a la fuerza general y posicionamiento estratégico de la familia.',
    'farms.how.step3.title': 'Apoyo Estratégico y CF Bombs',
    'farms.how.step3.desc': 'Al tener granjas en alianzas dedicadas, los miembros de la alianza principal pueden enfocarse en batallas y eventos mientras las granjas proporcionan apoyo esencial de recursos y posicionamiento estratégico. Durante KVK y operaciones importantes, estas granjas sirven como',
    'farms.how.step3.cf': 'CF Bombs',
    'farms.how.step3.end': '—activos tácticos críticos que proporcionan ventajas estratégicas y flexibilidad operativa cuando más los necesitamos.',
