    'main.alliance.members.title': 'Devoirs et Responsabilités des Membres',
    'main.alliance.member.active.title': 'Participation Active',
    'main.alliance.member.active.desc': 'Participation régulière aux événements, batailles et activités de l\'alliance. Votre présence et engagement renforcent notre famille. Assistez aux événements programmés, répondez aux appels de rassemblement et contribuez aux objectifs de l\'alliance.',
    'main.alliance.member.honor.title': 'Honneur et Respect',
    'main.alliance.member.honor.desc': 'Traitez chaque membre avec honneur et respect. Maintenez nos valeurs dans toutes les interactions, à la fois au sein et en dehors de l\'alliance. Montrez de la dignité à tous les guerriers, quelle que soit leur puissance ou expérience.',
    'main.alliance.member.loyalty.title': 'Loyauté et Engagement',
    'main.alliance.member.loyalty.desc': 'Restez fidèle à Blood Paladins et engagé envers nos objectifs partagés. Tenez avec votre famille à travers les victoires et les défis. Votre loyauté est le fondement de notre force.',
    'main.alliance.member.communication.title': 'Communication',
    'main.alliance.member.communication.desc': 'Maintenez une communication ouverte avec les dirigeants et officiers. Signalez les problèmes, partagez des idées et restez connecté avec la famille. Tenez les dirigeants informés de votre disponibilité et de toute préoccupation.',
    'main.alliance.member.growth.title': 'Croissance et Développement',
    'main.alliance.member.growth.desc': 'Travaillez continuellement à améliorer vos compétences et votre puissance. Soutenez les autres membres dans leur parcours de croissance. Aidez à former de nouveaux membres et partagez les connaissances avec la famille.',
    'main.alliance.member.sacrifice.title': 'Sacrifice et Soutien',
    'main.alliance.member.sacrifice.desc': 'Soyez prêt à soutenir les membres de votre famille lorsque nécessaire. Rappelez-vous : nous combattons ensemble, nous restons ensemble, nous mourons les uns pour les autres. Mettez les besoins de la famille au-dessus du gain personnel.',
    'main.alliance.member.resource.title': 'Gestion des Ressources',
    'main.alliance.member.resource.desc': 'Gérez vos ressources sagement et contribuez aux besoins de l\'alliance lorsque possible. Soutenez les efforts de collecte de ressources et partagez les ressources excédentaires avec les membres dans le besoin.',
    'main.alliance.member.battle.title': 'Préparation au Combat',
    'main.alliance.member.battle.desc': 'Maintenez vos armées et commandants en condition prête au combat. Répondez rapidement aux appels de bataille et suivez les instructions stratégiques pendant les opérations de combat.',
    'academy.title': 'Académie Paladins',
    'academy.description.p1': 'Le',
    'academy.description.p1.training': 'terrain d\'entraînement',
    'academy.description.p1.end': 'où les nouveaux guerriers commencent leur voyage avec Blood Paladins. Ici, les membres apprennent les fondamentaux, développent leurs compétences et se préparent à l\'avancement vers l\'alliance principale.',
    'academy.description.p2': 'Sous la guidance de dirigeants et officiers expérimentés, les membres de l\'Académie reçoivent un entraînement personnalisé, un mentorat et un soutien alors qu\'ils grandissent en guerriers d\'élite dignes de rejoindre l\'Alliance Principale de Blood Paladins.',
    'academy.leadership.title': 'Leadership de l\'Académie',
