    'main.alliance.members.title': 'Mitgliederpflichten und -verantwortlichkeiten',
    'main.alliance.member.active.title': 'Aktive Teilnahme',
    'main.alliance.member.active.desc': 'Regelmäßige Teilnahme an Allianzveranstaltungen, Schlachten und Aktivitäten. Deine Anwesenheit und Engagement stärken unsere Familie. Nimm an geplanten Veranstaltungen teil, reagiere auf Rallye-Aufrufe und trage zu Allianzzielen bei.',
    'main.alliance.member.honor.title': 'Ehre und Respekt',
    'main.alliance.member.honor.desc': 'Behandle jedes Mitglied mit Ehre und Respekt. Halte unsere Werte in allen Interaktionen aufrecht, sowohl innerhalb als auch außerhalb der Allianz. Zeige Würde gegenüber allen Kriegern, unabhängig von ihrer Macht oder Erfahrung.',
    'main.alliance.member.loyalty.title': 'Loyalität und Engagement',
    'main.alliance.member.loyalty.desc': 'Bleibe Blood Paladins treu und unseren gemeinsamen Zielen verpflichtet. Stehe mit deiner Familie durch Siege und Herausforderungen. Deine Loyalität ist das Fundament unserer Stärke.',
    'main.alliance.member.communication.title': 'Kommunikation',
    'main.alliance.member.communication.desc': 'Halte offene Kommunikation mit Führern und Offizieren aufrecht. Melde Probleme, teile Ideen und bleibe mit der Familie verbunden. Halte Führer über deine Verfügbarkeit und alle Bedenken informiert.',
    'main.alliance.member.growth.title': 'Wachstum und Entwicklung',
    'main.alliance.member.growth.desc': 'Arbeite kontinuierlich daran, deine Fähigkeiten und Macht zu verbessern. Unterstütze andere Mitglieder auf ihrem Wachstumsweg. Hilf, neue Mitglieder auszubilden und teile Wissen mit der Familie.',
    'main.alliance.member.sacrifice.title': 'Opfer und Unterstützung',
    'main.alliance.member.sacrifice.desc': 'Sei bereit, deine Familienmitglieder zu unterstützen, wenn nötig. Denke daran: Wir kämpfen zusammen, wir stehen zusammen, wir sterben füreinander. Stelle die Bedürfnisse der Familie über persönlichen Gewinn.',
    'main.alliance.member.resource.title': 'Ressourcenmanagement',
    'main.alliance.member.resource.desc': 'Verwalte deine Ressourcen weise und trage zu Allianzbedürfnissen bei, wenn möglich. Unterstütze Ressourcensammlungsbemühungen und teile überschüssige Ressourcen mit bedürftigen Mitgliedern.',
    'main.alliance.member.battle.title': 'Kampfbereitschaft',
    'main.alliance.member.battle.desc': 'Halte deine Armeen und Kommandanten in kampfbereitem Zustand. Reagiere schnell auf Schlachtaufrufe und folge strategischen Anweisungen während Kampfoperationen.',
    'academy.title': 'Paladins Akademie',
    'academy.description.p1': 'Das',
    'academy.description.p1.training': 'Ausbildungsgelände',
    'academy.description.p1.end': 'wo neue Krieger ihre Reise mit Blood Paladins beginnen. Hier lernen Mitglieder die Grundlagen, entwickeln ihre Fähigkeiten und bereiten sich auf den Aufstieg zur Hauptallianz vor.',
    'academy.description.p2': 'Unter der Anleitung erfahrener Führer und Offiziere erhalten Akademiemitglieder personalisierte Ausbildung, Mentoring und Unterstützung, während sie zu Elite-Kriegern heranwachsen, die es wert sind, der Blood Paladins Hauptallianz beizutreten.',
