    'join.academy.title': 'Paladins Akademie',
    'join.academy.subtitle': 'Ausbildungsgelände',
    'join.academy.about.title': 'Über die Paladins Akademie',
    'join.academy.about.p1': 'Das Ausbildungsgelände, wo neue Krieger ihre Reise mit Blood Paladins beginnen. Die Paladins Akademie ist für Mitglieder konzipiert, die die Grundlagen lernen, ihre Fähigkeiten entwickeln und sich auf den Aufstieg zur Hauptallianz vorbereiten.',
    'join.academy.about.p2': 'Unter der Anleitung erfahrener Führer und Offiziere erhalten Akademiemitglieder personalisierte Ausbildung, Mentoring und Unterstützung, während sie zu Elite-Kriegern heranwachsen, die es wert sind, der Blood Paladins Hauptallianz beizutreten. Hier beginnt deine Reise, hier lernst du, was es bedeutet, ein Blood Paladin zu sein.',
    'join.academy.offer.title': 'Was Wir Bieten:',
