    'join.farms.title': 'Farm-Allianzen',
    'join.farms.subtitle': 'Ressourcennetzwerk',
    'join.farms.about.title': 'Über Unsere Farm-Allianzen',
    'join.farms.about.p1': 'Unsere Farm-Allianzen (Paladins Farm1, Farm2 und Farm3) sind das Rückgrat des Ressourcennetzwerks unserer Familie. Diese Allianzen bieten wesentliche Unterstützung für die Hauptallianz durch strategische Ressourcensammlung und Positionierung.',
    'join.farms.about.p2': 'Jedes Mitglied von Blood Paladins kann seine Farmen an eine unserer Farm-Allianzen senden. Dies ermöglicht organisierte Ressourcenverwaltung, strategische Positionierung und stellt sicher, dass Hauptallianzmitglieder sich auf Schlachten und Veranstaltungen konzentrieren können, während Farmen sicher verwaltet und produktiv sind. Über Ressourcensammlung hinaus dienen unsere Farm-Allianzen als CF Bombs während KVK-Veranstaltungen und anderen wichtigen Operationen.',
    'join.farms.offer.title': 'Was Wir Bieten:',
