    'join.contact.title': 'Bereit Beizutreten?',
    'join.contact.description': 'Kontaktiere uns über Telegram oder Discord, um deinen Bewerbungsprozess zu starten.',
    'join.contact.details': 'Erzähle uns von dir, deinem Machtlevel, welcher Allianz du beitreten möchtest und warum du Teil der Blood Paladins Familie werden möchtest. Wir warten darauf, dich zu Hause willkommen zu heißen.',
